    import { BrowserRouter, Routes, Route } from "react-router-dom";
    import { AuthProvider } from "./context/AuthContext.jsx";
    import { Login } from "./pages/Login";
    import { Navbar } from "./components/Navbar.jsx";
    import Register from "./pages/Register.jsx";
    import Home from "./pages/Home.jsx";
    import { MyTeam } from "./pages/MyTeam.jsx";
    import { ProtectedRoute } from "./components/ProtectedRoute.jsx";
import { PointsTable } from "./pages/PointsTable.jsx";

    function App() {
        return (
            <AuthProvider>
                <BrowserRouter>
                <Navbar/>
                    <Routes>
                        <Route path="/login" element={<Login />} />
                        <Route path="/register" element={<Register/>} />
                        <Route path="/" element={<Home/>} />
                        <Route path="/MyTeam" element={<ProtectedRoute><MyTeam/></ProtectedRoute>} />
                        <Route path="/pointstable" element={<PointsTable/>}  />
                        <Route path="/createtournament" element={<ProtectedRoute></ProtectedRoute>}  />
                    </Routes>
                </BrowserRouter>
            </AuthProvider>
        );
    }

    export default App;
